package io.github.heapy.icu4k.impl

import io.github.heapy.icu4k.text.StringPrepParseException
import io.github.heapy.icu4k.util.ICUInputTooLongException
import kotlin.test.*

class PunycodeTest {
    @Test fun independentIcu4jGoldens() {
        // Generated by /private/tmp/PunycodeGoldens.java against pinned ICU4J 78.3.
        val vectors=listOf("" to "", "abc" to "abc-", "Bücher" to "Bcher-kva",
            "mañana" to "maana-pta", "日本語" to "wgv71a119e", "😀a𐀀" to "a-w10im802d",
            "Straße" to "Strae-oqa", "ليهمابتكلموشعربي؟" to "egbpdaj6bu4bxfgehfvwxn",
            "他们为什么不说中文" to "ihqwcrb4cv8a8dqg056pqjye")
        for((decoded,encoded) in vectors) {
            assertEquals(encoded,Punycode.encode(decoded,null).toString())
            assertEquals(decoded,Punycode.decode(encoded,null).toString())
        }
    }
    @Test fun boundsMalformedInputAndSourceCaseFlags() {
        for(c in listOf('\ud800','\udc00')) {
            val e=assertFailsWith<StringPrepParseException>{Punycode.encode(charArrayOf(c).concatToString(),null)}
            assertEquals(1,e.getError());assertEquals("Illegal char found",e.message)
        }
        assertFailsWith<ICUInputTooLongException>{Punycode.encode("a".repeat(1001),null)}
        assertFailsWith<ICUInputTooLongException>{Punycode.decode("a".repeat(2001),null)}
        assertEquals(0,assertFailsWith<StringPrepParseException>{Punycode.decode("!",null)}.getError())
        assertEquals(1,assertFailsWith<StringPrepParseException>{Punycode.decode("z",null)}.getError())
        val flags=BooleanArray(4)
        assertEquals("AZaz",Punycode.decode("AZaz-",flags).toString())
        assertContentEquals(booleanArrayOf(false,true,true,true),flags)
        val error=StringPrepParseException("bad",7)
        assertEquals(StringPrepParseException("different",7),error)
        assertEquals("bad. line:  0. preContext:  . postContext: \n",error.toString())
    }
}
